<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: 'admin' })
const { t, locale } = useI18n()
useSeoMeta({ title: () => t('操作日志') })
const { draft, filters, filterError, apply, reset } = useAdminDateFilters()
const offset = ref(0)
const query = computed(() => ({ ...filters.value, offset: offset.value, limit: 20 }))
function search() { if (apply()) offset.value = 0 }
const { result, error, pending, refresh } = useApiList<{ id: string; email: string | null; action: string; target: string; changed_fields: string[]; created_at: string }>('/api/v1/admin/audit', query)
</script>
<template><div><div class="admin-page-heading"><h1>{{ $t('操作日志') }}</h1></div><form class="admin-toolbar payment-filters" @submit.prevent="search"><input v-model="draft.q" class="filter-input" :aria-label="$t('搜索操作者、操作或目标')" :placeholder="$t('搜索操作者、操作或目标')" maxlength="100"><label class="date-filter">{{ $t('开始日期') }}<input v-model="draft.start" type="date"></label><label class="date-filter">{{ $t('结束日期') }}<input v-model="draft.end" type="date"></label><button class="button primary">{{ $t('查询') }}</button><button class="text-button" type="button" @click="offset = 0; reset()">{{ $t('重置筛选') }}</button><button class="icon-button" type="button" :title="$t('刷新')" :aria-label="$t('刷新')" :disabled="pending" @click="refresh"><AppIcon name="refresh" :size="18" /></button></form><p class="payment-help">{{ $t('日期使用本地时区，包含结束当天。日志仅记录变更字段名，不显示密钥或原始内容。') }}</p><p v-if="filterError" class="form-error" role="alert">{{ filterError }}</p><AsyncState v-if="error" kind="error" :title="$t('操作日志加载失败')" :description="error" @retry="refresh" /><AsyncState v-else-if="pending" kind="loading" :title="$t('正在加载数据')" /><AsyncState v-else-if="!result.items.length" kind="empty" :title="$t('暂无操作日志')" :description="$t('尝试调整筛选条件。')" /><div v-else class="admin-table-scroll"><table class="admin-table"><thead><tr><th>{{ $t('操作者') }}</th><th>{{ $t('操作类型') }}</th><th>{{ $t('目标') }}</th><th>{{ $t('变更字段') }}</th><th>{{ $t('时间') }}</th></tr></thead><tbody><tr v-for="row in result.items" :key="row.id"><td>{{ row.email || '-' }}</td><td>{{ row.action }}</td><td class="audit-target">{{ row.target }}</td><td>{{ row.changed_fields.join(', ') }}</td><td>{{ new Date(row.created_at).toLocaleString(locale) }}</td></tr></tbody></table></div><AdminPagination :total="result.total" :offset="offset" :limit="20" :busy="pending" @change="offset = $event" /></div></template>
